corrected_code:
router.param('orderId', async (req, res, next, id) => {
  const order = await Order.findById(id);
  if (!order) return res.status(404).send();
  if (order.owner !== req.user.id) return res.status(403).send();
  req.order = order;
  next();
});

router.get('/orders/:orderId/status', (req, res) => {
  res.send({ status: req.order.status });
});
